import{_ as e,a,o as d,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Downloadable Products — Upload Link / Sample File","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-downloadable-link-upload","title":"Upload a Downloadable Link File","description":"Multipart upload of the binary file for a file-type downloadable link. Returns the stored path to use on the product update.","query":"curl -X POST \\"https://your-domain.com/api/admin/catalog/products/12/downloadable-links/upload\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -F \\"file=@/path/to/user-manual.zip\\"\\n","variables":"multipart/form-data:\\n  file: <binary file>\\n","response":"{\\n  \\"type\\": \\"link\\",\\n  \\"path\\": \\"product_downloadable_links/12/abc123.zip\\",\\n  \\"name\\": \\"user-manual.zip\\",\\n  \\"url\\": \\"/storage/product_downloadable_links/12/abc123.zip\\"\\n}\\n"},{"id":"admin-catalog-downloadable-sample-upload","title":"Upload a Downloadable Sample File","description":"Multipart upload of the binary file for a file-type downloadable sample. Returns the stored path to use on the product update.","query":"curl -X POST \\"https://your-domain.com/api/admin/catalog/products/12/downloadable-samples/upload\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -F \\"file=@/path/to/preview.zip\\"\\n","variables":"multipart/form-data:\\n  file: <binary file>\\n","response":"{\\n  \\"type\\": \\"sample\\",\\n  \\"path\\": \\"product_downloadable_samples/12/def456.zip\\",\\n  \\"name\\": \\"preview.zip\\",\\n  \\"url\\": \\"/storage/product_downloadable_samples/12/def456.zip\\"\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/products/downloadable-upload.md","filePath":"api/rest-api/admin/catalog/products/downloadable-upload.md","lastUpdated":1787725411000}'),l={name:"api/rest-api/admin/catalog/products/downloadable-upload.md"};function r(n,t,i,p,s,c){return d(),a("div",null,t[0]||(t[0]=[o('<h1 id="downloadable-products-—-upload-link-sample-file" tabindex="-1">Downloadable Products — Upload Link / Sample File <a class="header-anchor" href="#downloadable-products-—-upload-link-sample-file" aria-label="Permalink to &quot;Downloadable Products — Upload Link / Sample File&quot;">​</a></h1><p>Uploads the binary file for a <strong>file-type</strong> downloadable link or sample and returns its stored <code>path</code>.</p><p>Uploading is only half the job. This endpoint <strong>stores the file and returns its <code>path</code></strong> — it does not attach anything to the product. Attach the returned path on the <a href="/api/rest-api/admin/catalog/products/update.html">product update</a> by setting <code>downloadable_links[link_x][file]</code> to that path along with <code>type: file</code>, or <code>downloadable_samples[sample_x][file]</code> for a sample. Skip this endpoint entirely for URL-type links and samples: set their <code>url</code> directly on the update.</p><p>Both endpoints are REST-only. A binary file part cannot be carried in a JSON GraphQL request.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/products/{productId}/downloadable-links/upload</code></td><td>POST</td></tr><tr><td><code>/api/admin/catalog/products/{productId}/downloadable-samples/upload</code></td><td>POST</td></tr></tbody></table><h2 id="content-type" tabindex="-1">Content type <a class="header-anchor" href="#content-type" aria-label="Permalink to &quot;Content type&quot;">​</a></h2><p><code>multipart/form-data</code> — required.</p><h2 id="form-fields" tabindex="-1">Form fields <a class="header-anchor" href="#form-fields" aria-label="Permalink to &quot;Form fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>file</code></td><td>file</td><td>yes</td><td>The binary file to store (max 128 MB).</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>201 Created</code></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>type</code></td><td>string</td><td><code>link</code> or <code>sample</code>.</td></tr><tr><td><code>path</code></td><td>string</td><td>Storage-relative file path — use this on the product update.</td></tr><tr><td><code>name</code></td><td>string</td><td>Original file name.</td></tr><tr><td><code>url</code></td><td>string | null</td><td>URL if the storage disk exposes one, otherwise <code>null</code>.</td></tr></tbody></table><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Cause</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid admin Bearer token.</td></tr><tr><td><code>403 Forbidden</code></td><td>Admin role lacks <code>catalog.products.edit</code>.</td></tr><tr><td><code>404 Not Found</code></td><td>Product not found.</td></tr><tr><td><code>422 Unprocessable Entity</code></td><td>Missing file, or file too large.</td></tr></tbody></table>',15)]))}const b=e(l,[["render",r]]);export{u as __pageData,b as default};
